func:
switch (msg.topic) {
    case "lowResN":
        flow.set("lowResN", msg.payload);
        break;
    case "highResN":
        flow.set("highResN", msg.payload);
        break;
    default:
}

if (flow.get("combineResBanks") == false) {
    switch (msg.topic) {
        case "lowResN":
            flow.set("highResN", 0);
            return ([null, null, msg]);
        case "highResN":
            flow.set("lowResN", 0);
            return ([msg, null, null]);
        default:
    }
}
else {
    var outputMsg = {};
    outputMsg.payload = "";
    var buf = Buffer.alloc(2);
    var highResN = 0;
    var lowResN = 0;

    lowResN = flow.get("lowResN");
    highResN = flow.get("highResN");

    for (let index = 0; index < lowResN; index++) {
        buf[1] = buf[1] | (1 << index);
    }
    for (let index = 0; index < highResN; index++) {
        buf[0] = buf[0] | (1 << index);
    }

    outputMsg.payload = buf.readUInt16BE(0).toString(16);
    return ([null, outputMsg, null]);
}

